import{_ as o,C as s,c as n,o as l,a3 as r,G as t}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Departure reasons","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/setup/departure-reasons.md","filePath":"master/human-resources/employees/setup/departure-reasons.md","lastUpdated":1791902625000}'),i={name:"master/human-resources/employees/setup/departure-reasons.md"};function p(d,e,u,h,c,m){const a=s("ImagePopup");return l(),n("div",null,[e[0]||(e[0]=r('<h1 id="departure-reasons" tabindex="-1">Departure reasons <a class="header-anchor" href="#departure-reasons" aria-label="Permalink to &quot;Departure reasons&quot;">​</a></h1><p>A departure reason records why a person left the company, such as Resigned or Retired. You choose it on the employee when they leave. Keeping a fixed list lets you compare reasons over time.</p><blockquote><p><strong>In simple words:</strong> A departure reason is the answer to &quot;why did this person leave?&quot;</p></blockquote><p>Open <code>Employees → Configurations → Departure Reasons</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>None. The sample data has three reasons: <strong>Retired</strong>, <strong>Resigned</strong> and <strong>Fired</strong>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list has one column, <strong>Name</strong>. Drag the handle on a row to change the order. A filter panel and search help you find a reason.</p>',7)),t(a,{src:"/images1/employees/set_departure_list.png",alt:"Departure Reasons list showing Retired, Resigned and Fired"}),e[1]||(e[1]=r('<h2 id="create-a-departure-reason" tabindex="-1">Create a departure reason <a class="header-anchor" href="#create-a-departure-reason" aria-label="Permalink to &quot;Create a departure reason&quot;">​</a></h2><p>This example adds <strong>Contract ended</strong>.</p><ol><li>Open <code>Employees → Configurations → Departure Reasons</code>.</li><li>Click <strong>New Departure Reason</strong>. A window opens.</li><li>Fill in the form.</li></ol><ul><li><strong><em>Name:</em></strong> Required. Type <code>Contract ended</code>.</li></ul>',4)),t(a,{src:"/images1/employees/set_departure_form.png",alt:"Create Departure Reasons window with the name Contract ended"}),e[2]||(e[2]=r('<ol start="4"><li>Click <strong>Create</strong>.</li></ol><h2 id="where-departure-reasons-are-used" tabindex="-1">Where departure reasons are used <a class="header-anchor" href="#where-departure-reasons-are-used" aria-label="Permalink to &quot;Where departure reasons are used&quot;">​</a></h2><p>On the employee form, open the <strong>Settings</strong> tab and choose a <strong>Departure Reason</strong>. Two required fields then appear: <strong>Departure Date</strong> and <strong>Departure Description</strong>.</p><p>You can group the employee list by <strong>Departure Reason</strong>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The plus button next to the field on the employee form also creates a reason.</p></div><h2 id="edit-or-delete" tabindex="-1">Edit or delete <a class="header-anchor" href="#edit-or-delete" aria-label="Permalink to &quot;Edit or delete&quot;">​</a></h2><p>Click <strong>Edit</strong> on a row to rename it. Click <strong>Delete</strong> to remove it.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../employees/leaving-the-company.html">Leaving the company</a></li><li><a href="./../employees/employee-list.html">Employee list</a></li><li><a href="./">Setup overview</a></li></ul>',9))])}const f=o(i,[["render",p]]);export{_ as __pageData,f as default};
